// Kinetic: hang-gliding page script (generated by kinetic-tools/build/build.py)
(function () {
  const PAGE = {
    key: "hang-gliding",
    v1: "Physics: nailed it 🪂",
    b1: "You've got the physics of lift, glide, weight-shift control, wind and towing. Skim the chapters for anything you missed, then scroll to “Where to learn” for your next step. Knowing the science is a start; on the hill, the instructor, the conditions and your rating still set the limits.",
    b2: "You have the basics. Fill the gaps below before you fly, especially wind and turns: they explain why launches, landings and low turns go wrong.",
    b3: "No shame in that: this is exactly what the chapters are for. Read the ones linked below, then take the challenge again.",
    whereLabel: "Where to learn at my level →",
    disclaimer: "<strong>Self-check only.</strong> This quiz is a learning aid. It is not a certification and not a pilot rating: hang-gliding ratings are issued by national bodies under CIVL's standards. Learn only with a qualified instructor, fly within your stage, and never fly in conditions you haven't trained for."
  };
  const CHAPTERS = {
    "ch-wing":    "Ch 1 · The rigid wing: lift, glide ratio & speed",
    "ch-control": "Ch 2 · Weight-shift control & pitch stability",
    "ch-launch":  "Ch 3 · Launch, landing & the wind",
    "ch-turns":   "Ch 4 · Turns, stalls & turbulence",
    "ch-tow":     "Ch 5 · Towing & the weak link"
  };
  const QUESTIONS = [
    { ch: "ch-wing",
      q: "A hang glider with a 15:1 glide ratio is 300 m above its landing field in still air. How far can it glide?",
      o: ["4.5 km", "300 m", "15 km", "2 km"], a: 0,
      e: "Distance = height × glide ratio = 300 × 15 = 4,500 m. Sinking air or a headwind cuts it." },
    { ch: "ch-wing",
      q: "Lift is L = ½ ρ v² S C<sub>L</sub>. If you fly 1.5 times faster, how does the lift available at the same angle change?",
      o: ["It halves", "It stays the same", "It rises about 2.25 times", "It rises 1.5 times"], a: 2,
      e: "Lift goes with v², so 1.5² = 2.25. That's why at higher speed the wing needs a much smaller angle of attack to carry the same weight." },
    { ch: "ch-wing",
      q: "Compared with a paraglider, why does a hang glider glide further?",
      o: ["It's heavier", "Its rigid frame holds an efficient wing shape at higher speed: about 17:1 against about 10:1", "It has an engine", "It flies lower"], a: 1,
      e: "Wikipedia gives about 17:1 for a topless flex wing and about 10:1 for a paraglider at best: a better lift-to-drag ratio." },
    { ch: "ch-control",
      q: "How does a hang-glider pilot turn?",
      o: ["With rudder pedals", "By pulling brake lines", "By moving their body weight sideways under the wing", "By leaning the control bar forward"], a: 2,
      e: "Weight shift: moving your centre of mass sideways makes a moment (M = F × d) that rolls the wing into the turn." },
    { ch: "ch-control",
      q: "You push the control bar out, away from you. What happens?",
      o: ["Your weight moves back, the nose rises and you slow down", "You speed up", "You turn left", "Nothing: the bar only steers"], a: 0,
      e: "Pushing out moves your weight back relative to the wing, pitching the nose up and slowing the glider; too far and it stalls." },
    { ch: "ch-control",
      q: "What is the specific failure a hang glider's rigid frame risks that a paraglider's soft wing doesn't?",
      o: ["A collapse", "A tumble: pitching over end to end", "A line twist", "A fabric tear"], a: 1,
      e: "A rigid wing can't collapse, but pitched past recovery (for example after being unloaded by turbulence) it can tumble, which typically breaks it. Pilots carry a reserve parachute for pilot and glider." },
    { ch: "ch-launch",
      q: "Your glider flies at 30 km/h airspeed. You launch into a steady 15 km/h headwind. How fast must you run over the ground?",
      o: ["45 km/h", "30 km/h", "About 15 km/h", "0 km/h"], a: 2,
      e: "Ground speed = airspeed − headwind = 30 − 15 = 15 km/h. Into the wind, you need to run much less." },
    { ch: "ch-launch",
      q: "At 30 km/h airspeed, how much more energy does a landing with a 10 km/h tailwind carry than one into a 15 km/h headwind?",
      o: ["About 7 times", "About 2 times", "The same", "Less"], a: 0,
      e: "Ground speeds are 40 and 15 km/h. Energy goes with speed squared: (40 ÷ 15)² ≈ 7." },
    { ch: "ch-launch",
      q: "Why does wind matter more than it seems on launch?",
      o: ["Wind force grows with the square of wind speed", "Wind only matters above 1,000 m", "Wind has no force on a rigid wing", "Wind force grows with the cube of altitude"], a: 0,
      e: "CIVL's SafePro Delta reminds students that wind force increases with the square of wind velocity: double the wind, four times the force." },
    { ch: "ch-turns",
      q: "In a level turn at 60° of bank, what load factor must the wing carry?",
      o: ["1 g", "1.41 g", "3 g", "2 g"], a: 3,
      e: "n = 1 ÷ cos 60° = 2. The wing holds up twice your weight." },
    { ch: "ch-turns",
      q: "If the wings-level stall speed is 30 km/h, roughly what is it in a 60° banked turn?",
      o: ["30 km/h", "About 42 km/h", "60 km/h", "About 21 km/h"], a: 1,
      e: "Stall speed rises with √n = √2 ≈ 1.41, so 30 × 1.41 ≈ 42 km/h. A steep low turn can stall the wing near the ground." },
    { ch: "ch-turns",
      q: "Which does CIVL's SafePro Delta tell early-stage pilots to strictly avoid close to the ground?",
      o: ["Flying into wind", "Using a helmet", "Landing in a large field", "Turns, downwind flying and slow speeds"], a: 3,
      e: "Near the ground there's no height to recover from a stall or a misjudged turn, so these are avoided at Stage 2." },
    { ch: "ch-tow",
      q: "What does the weak link on a tow line do?",
      o: ["Holds the glider to the ground", "Snaps first, so the line can't pull the glider much harder than its own weight", "Measures airspeed", "Joins the reserve parachute"], a: 1,
      e: "NZHGPA's aerotow manual: the glider weak link breaks at about 1 g, normally 90–100 kg." },
    { ch: "ch-tow",
      q: "What is a lockout?",
      o: ["Losing the keys to the winch", "A locked harness buckle", "A stalled engine", "The glider swinging off the line of the tow, so tension rises"], a: 3,
      e: "A lockout pulls the glider further off course as tension grows; the weak link should break before it's too late." },
    { ch: "ch-tow",
      q: "A weak link breaks at 90–100 kg. Roughly what force is that?",
      o: ["About 0.9–1 kN", "About 9–10 N", "About 90–100 kN", "About 9–10 kN"], a: 0,
      e: "F = m g: 90 × 9.81 ≈ 0.88 kN and 100 × 9.81 ≈ 0.98 kN." }
  ];

  // ---------- QUIZ RENDER ----------
  const list = document.getElementById("quiz-list");
  const dots = document.getElementById("quiz-dots");
  const prog = document.getElementById("quiz-progress");
  const progLabel = document.getElementById("quiz-progress-label");
  const warn = document.getElementById("quiz-warn");
  const resultBox = document.getElementById("quiz-result");
  let graded = false;

  function esc(s) { return s.replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

  QUESTIONS.forEach((item, i) => {
    const n = i + 1;
    const div = document.createElement("div");
    div.className = "q";
    div.id = "q" + n;
    div.dataset.index = i;
    div.innerHTML =
      `<span class="qtag">${esc(CHAPTERS[item.ch].split(" · ")[1])}</span>` +
      `<span class="qnum">Question ${n} / ${QUESTIONS.length}</span>` +
      `<h3>${esc(item.q)}</h3>` +
      `<div class="opts" role="radiogroup" aria-label="Question ${n}">` +
      item.o.map((opt, j) =>
        `<label class="opt"><input type="radio" name="q${n}" value="${j}"><span>${esc(opt)}</span><span class="mark"></span></label>`
      ).join("") +
      `</div><div class="explain" aria-live="polite"></div>`;
    list.appendChild(div);

    const d = document.createElement("a");
    d.href = "#q" + n; d.textContent = n; d.id = "dot" + n;
    d.setAttribute("aria-label", "Go to question " + n);
    dots.appendChild(d);
  });

  function answeredCount() {
    return QUESTIONS.filter((_, i) => document.querySelector(`input[name="q${i + 1}"]:checked`)).length;
  }
  function updateProgress() {
    const c = answeredCount();
    prog.style.width = (c / QUESTIONS.length * 100) + "%";
    progLabel.textContent = `${c} of ${QUESTIONS.length} answered`;
  }

  list.addEventListener("change", (ev) => {
    if (graded || ev.target.type !== "radio") return;
    const q = ev.target.closest(".q");
    q.querySelectorAll(".opt").forEach(l => l.classList.toggle("sel", l.querySelector("input").checked));
    document.getElementById("dot" + (+q.dataset.index + 1)).classList.add("answered");
    updateProgress();
    warn.style.display = "none";
  });

  function grade() {
    const unanswered = QUESTIONS.length - answeredCount();
    if (unanswered > 0 && !document.getElementById("quiz-submit").dataset.confirmed) {
      warn.textContent = `${unanswered} question${unanswered > 1 ? "s" : ""} unanswered. They'll count as wrong. Press submit again to score anyway.`;
      warn.style.display = "block";
      document.getElementById("quiz-submit").dataset.confirmed = "1";
      return;
    }
    graded = true;
    let score = 0;
    const wrongChapters = new Map();
    QUESTIONS.forEach((item, i) => {
      const n = i + 1;
      const qEl = document.getElementById("q" + n);
      const picked = document.querySelector(`input[name="q${n}"]:checked`);
      const pickedIdx = picked ? +picked.value : -1;
      const right = pickedIdx === item.a;
      if (right) score++;
      else wrongChapters.set(item.ch, (wrongChapters.get(item.ch) || []).concat(n));
      qEl.classList.add("graded", right ? "right" : (picked ? "wrong" : "skipped"));
      qEl.querySelectorAll("input").forEach(inp => inp.disabled = true);
      qEl.querySelectorAll(".opt").forEach((lab, j) => {
        if (j === item.a) { lab.classList.add("correct"); lab.querySelector(".mark").textContent = "✓ correct"; }
        else if (j === pickedIdx) { lab.classList.add("incorrect"); lab.querySelector(".mark").textContent = "✗ your pick"; }
      });
      const ex = qEl.querySelector(".explain");
      ex.innerHTML = `<span class="verdict">${right ? "Correct." : (picked ? "Not quite." : "Skipped.")}</span> ${esc(item.e)}` +
        (right ? "" : `<br><a class="chlink" href="#${item.ch}" data-wrong-link="${item.ch}">Read ${esc(CHAPTERS[item.ch])} →</a>`);
      const dot = document.getElementById("dot" + n);
      dot.classList.remove("answered"); dot.classList.add(right ? "right" : "wrong");
    });

    const pct = score / QUESTIONS.length;
    let lvl, title, blurb;
    if (pct >= 0.8) { lvl = "lvl-ready"; title = PAGE.v1; blurb = PAGE.b1; }
    else if (pct >= 0.55) { lvl = "lvl-close"; title = "Nearly there. Brush up on a couple of chapters"; blurb = PAGE.b2; }
    else { lvl = "lvl-brush"; title = "Brush up first"; blurb = PAGE.b3; }

    resultBox.className = "result show " + lvl;
    const chItems = [...wrongChapters.entries()].map(([ch, qs]) =>
      `<li><a href="#${ch}" data-summary-link="${ch}">${esc(CHAPTERS[ch])}</a> <span class="small">(question${qs.length > 1 ? "s" : ""} ${qs.join(", ")})</span></li>`).join("");
    resultBox.innerHTML =
      `<div class="score" id="quiz-score">${score}<small> / ${QUESTIONS.length}</small></div>` +
      `<h3 id="quiz-verdict">${title}</h3><p>${blurb}</p>` +
      `<div class="result-note" id="quiz-disclaimer" role="note" data-reel-hide>${PAGE.disclaimer}</div>` +
      (chItems ? `<strong>Chapters to read:</strong><ul id="quiz-revisit">${chItems}</ul>` : `<p><strong>Perfect score.</strong> The chapters still have the worked numbers if you want to go deeper.</p>`) +
      `<div class="actions"><button class="btn btn-ghost" type="button" id="quiz-retake">↺ Retake the challenge</button><a class="btn btn-ghost" href="${PAGE.whereHref || "#where"}">${PAGE.whereLabel}</a></div>`;
    document.getElementById("quiz-retake").addEventListener("click", resetQuiz);
    document.getElementById("quiz-submit").style.display = "none";
    warn.style.display = "none";
    resultBox.scrollIntoView({ behavior: "smooth", block: "start" });
    try { localStorage.setItem("kinetic-" + PAGE.key + "-last", JSON.stringify({ score, of: QUESTIONS.length, at: Date.now() })); } catch (e) {}
  }

  function resetQuiz() {
    graded = false;
    resultBox.className = "result"; resultBox.innerHTML = "";
    document.querySelectorAll(".q").forEach(q => {
      q.className = "q";
      q.querySelector(".explain").innerHTML = "";
      q.querySelectorAll("input").forEach(i => { i.checked = false; i.disabled = false; });
      q.querySelectorAll(".opt").forEach(l => { l.className = "opt"; l.querySelector(".mark").textContent = ""; });
    });
    document.querySelectorAll("#quiz-dots a").forEach(d => d.className = "");
    const sub = document.getElementById("quiz-submit");
    sub.style.display = ""; delete sub.dataset.confirmed;
    updateProgress();
    document.getElementById("q1").scrollIntoView({ behavior: "smooth", block: "start" });
  }

  document.getElementById("quiz-submit").addEventListener("click", grade);
  document.getElementById("quiz-reset").addEventListener("click", resetQuiz);
  updateProgress();

  // Expose for automated tests
  window.KINETIC_QUIZ = { QUESTIONS, CHAPTERS, grade, resetQuiz };


  // ---------- GLIDE LAB ----------
  // Steady glide in smooth air: still-air distance = h × GR; sink = V ÷ GR; time = h ÷ sink.
  // Ground distance = (V − headwind) × time; paraglider comparison at 10:1 (Wikipedia). Illustrative only.
  (function () {
    const $ = id => document.getElementById(id);
    if (!$("hg-h")) return;
    function update() {
      const h = +$("hg-h").value, gr = +$("hg-gr").value, v = +$("hg-v").value, w = +$("hg-w").value;
      $("hg-h-o").textContent = h + " m";
      $("hg-gr-o").textContent = gr + ":1";
      $("hg-v-o").textContent = v + " km/h";
      $("hg-w-o").textContent = w + " km/h";
      const V = v / 3.6, sink = V / gr, t = h / sink, d0 = h * gr, dg = Math.max(0, (v - w) / 3.6) * t;
      $("hg-d0").textContent = (d0 / 1000).toFixed(2) + " km";
      $("hg-sink").textContent = sink.toFixed(2) + " m/s";
      $("hg-t").textContent = (t / 60).toFixed(1) + " min";
      $("hg-dg").textContent = (dg / 1000).toFixed(2) + " km";
      $("hg-ge").textContent = (dg / h).toFixed(1) + ":1";
      $("hg-pg").textContent = (h * 10 / 1000).toFixed(2) + " km";
      $("hg-bar").style.width = Math.min(100, 100 * dg / d0).toFixed(0) + "%";
    }
    ["hg-h", "hg-gr", "hg-v", "hg-w"].forEach(id => $(id).addEventListener("input", update));
    update();
  })();

  // ---------- LEVEL TABS ----------
  const tabs = document.querySelectorAll(".lvl-tabs button");
  tabs.forEach(btn => btn.addEventListener("click", () => {
    tabs.forEach(b => b.setAttribute("aria-selected", b === btn ? "true" : "false"));
    document.querySelectorAll(".lvl-panel").forEach(p => p.classList.toggle("show", p.id === btn.getAttribute("aria-controls")));
  }));
  // a link or URL hash to #lvl-x opens that tab (and scrolls to the tabs), even after the visitor switched tabs
  const openLvl = (hash, scroll) => {
    const btn = /^#lvl-[\w-]+$/.test(hash || "") && [...tabs].find(b => "#" + b.getAttribute("aria-controls") === hash);
    if (!btn) return false;
    if (btn.getAttribute("aria-selected") !== "true") btn.click();
    if (scroll) { (btn.closest(".lvl-tabs") || btn).scrollIntoView({ block: "start" }); btn.focus({ preventScroll: true }); }
    return true;
  };
  document.addEventListener("click", e => {
    const a = e.target.closest && e.target.closest('a[href^="#lvl-"]');
    if (a && openLvl(a.getAttribute("href"), true)) { e.preventDefault(); if (location.hash !== a.getAttribute("href")) history.pushState(null, "", a.getAttribute("href")); }
  });
  window.addEventListener("hashchange", () => openLvl(location.hash, true));
  openLvl(location.hash, true);

  // ---------- STICKY NAV ACTIVE STATE ----------
  const navLinks = [...document.querySelectorAll(".sectionnav a[href^='#']")];
  const targets = navLinks.map(a => document.querySelector(a.getAttribute("href"))).filter(Boolean);
  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver(entries => {
      entries.forEach(en => {
        if (en.isIntersecting) {
          navLinks.forEach(a => a.classList.toggle("active", a.getAttribute("href") === "#" + en.target.id));
        }
      });
    }, { rootMargin: "-45% 0px -50% 0px" });
    targets.forEach(t => io.observe(t));
  }

  // ---------- MOBILE NAV: edge fades + keep the active link in view ----------
  (function () {
    const snav = document.querySelector(".sectionnav");
    if (!snav) return;
    const fades = () => {
      const max = snav.scrollWidth - snav.clientWidth;
      snav.classList.toggle("fade-l", max > 4 && snav.scrollLeft > 4);
      snav.classList.toggle("fade-r", max > 4 && snav.scrollLeft < max - 4);
    };
    snav.addEventListener("scroll", fades, { passive: true });
    window.addEventListener("resize", fades);
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(fades);
    fades();
    const keep = () => {
      const a = snav.querySelector("a.active");
      if (!a || snav.scrollWidth <= snav.clientWidth + 4) return;
      const r = a.getBoundingClientRect(), n = snav.getBoundingClientRect();
      if (r.left < n.left + 16 || r.right > n.right - 40) snav.scrollBy({ left: r.left - n.left - 20, behavior: "smooth" });
    };
    if ("MutationObserver" in window) {
      const mo = new MutationObserver(keep);
      snav.querySelectorAll("a").forEach(a => mo.observe(a, { attributes: true, attributeFilter: ["class"] }));
    }
  })();
})();
